const products = [
  { id: 'p1', name: 'Keyboard', cents: 4900 },
  { id: 'p2', name: 'Mouse', cents: 1900 },
];

export default function App() {
  return (
    <Layout>
      <ProductList products={products} />
    </Layout>
  );
}

function ProductList({ products }) {
  return (
    <ul className="grid">
      {products.map((product) => (
        <li key={product.id}>
          <ProductCard product={product} />
        </li>
      ))}
    </ul>
  );
