function SearchResults({ status, results, error }) {
  if (status === 'loading') return <p role="status">Searching…</p>;
  if (status === 'error') return <p role="alert">The search failed: {error}</p>;
  if (results.length === 0) return <p>Nothing found. Try another word.</p>;

  return (
    <ul>
      {results.map((result) => (
        <li key={result.id}>
          <a href={result.url}>{result.title}</a>
        </li>
      ))}
    </ul>
  );
}

function InboxHeading({ unread }) {
  return (
    <h1>
      Inbox {unread > 0 && <span className="badge">{unread} new</span>}
    </h1>
  );
}

// With {unread && <span>…</span>}, the heading reads "Inbox 0" when unread is 0:
// && returns its left side, and React renders numbers.

import { useState } from 'react';

export function Counter() {
  const [count, setCount] = useState(0);

  function addThree() {
    setCount((c) => c + 1);
    setCount((c) => c + 1);
    setCount((c) => c + 1);
  }

  return (
    <>
      <p>Count: {count}</p>
      <button type="button" onClick={() => setCount(count + 1)}>
        Add one
      </button>
      <button type="button" onClick={addThree}>
        Add three
      </button>
    </>
  );
}

import { useState } from 'react';

export function Greeting() {
  const [name, setName] = useState('');
  const trimmed = name.trim(); // derived while rendering, not stored

  return (
    <>
      <label htmlFor="name">Your name</label>
      <input id="name" value={name} onChange={(event) => setName(event.target.value)} />
      <p>{trimmed ? `Hello, ${trimmed}!` : 'Type your name to be greeted.'}</p>
    </>
  );
}

import { useState } from 'react';

export function TodoApp() {
  const [todos, setTodos] = useState([{ id: 1, title: 'Learn useState', done: false }]);
  const [title, setTitle] = useState('');

  function handleSubmit(event) {
    event.preventDefault();
    if (!title.trim()) return;
    setTodos((list) => [...list, { id: Date.now(), title: title.trim(), done: false }]);
    setTitle('');
  }

  function toggle(id) {
    setTodos((list) => list.map((todo) => (todo.id === id ? { ...todo, done: !todo.done } : todo)));
  }

  return (
    <form onSubmit={handleSubmit}>
      <input aria-label="New todo" value={title} onChange={(event) => setTitle(event.target.value)} />
      <button type="submit">Add</button>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            <label>
              <input type="checkbox" checked={todo.done} onChange={() => toggle(todo.id)} /> {todo.title}
            </label>
          </li>
        ))}
      </ul>
    </form>
  );
}

import { useEffect, useState } from 'react';

export function Clock() {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id); // stop the timer when the clock leaves the page
  }, []);

  return <time dateTime={now.toISOString()}>{now.toLocaleTimeString()}</time>;
}

import { useEffect, useState } from 'react';

export function WindowWidth() {
  const [width, setWidth] = useState(() => window.innerWidth);

  useEffect(() => {
    const onResize = () => setWidth(window.innerWidth);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  return <p>The window is {width}px wide.</p>;
}

import { useEffect, useState } from 'react';

// Before: an effect copies a calculation into state. The first render shows a stale total,
// then the effect sets it and React renders again.
function CartTotalWithEffect({ items }) {
  const [total, setTotal] = useState(0);
  useEffect(() => {
    setTotal(items.reduce((sum, item) => sum + item.price * item.quantity, 0));
  }, [items]);
  return <p>Total: {total}</p>;
}

// After: calculate it while rendering. Always right, and one render instead of two.
function CartTotal({ items }) {
  const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  return <p>Total: {total}</p>;
}

import { useEffect, useState } from 'react';

export function useOnlineStatus() {
  const [online, setOnline] = useState(() => navigator.onLine);
  useEffect(() => {
    const update = () => setOnline(navigator.onLine);
    window.addEventListener('online', update);
    window.addEventListener('offline', update);
    return () => {
      window.removeEventListener('online', update);
      window.removeEventListener('offline', update);
    };
  }, []);
  return online;
}

function SaveButton() {
  const online = useOnlineStatus();
  return (
    <button type="submit" disabled={!online}>
      {online ? 'Save' : 'Reconnecting…'}
    </button>
  );
}

import { useEffect, useState } from 'react';

export function useDebounce(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // a newer value arrived first: drop this one
  }, [value, delay]);
  return debounced;
}

function CitySearch() {
  const [query, setQuery] = useState('');
  const debouncedQuery = useDebounce(query, 300);
  // Fetch results for debouncedQuery here: one request after the user pauses, not one per key.
  return <input aria-label="City" value={query} onChange={(event) => setQuery(event.target.value)} />;
}

import { useCallback, useState } from 'react';

export function useToggle(initial = false) {
  const [on, setOn] = useState(initial);
  const toggle = useCallback(() => setOn((value) => !value), []);
  return [on, toggle];
}

function Question({ question, answer }) {
  const [open, toggle] = useToggle();
  return (
    <div>
      <button type="button" aria-expanded={open} onClick={toggle}>
        {question}
      </button>
      {open && <p>{answer}</p>}
    </div>
  );
}
